// Шукаємо блок тексту, який починається з { і закінчується на }
const match = $json.output.match(/\{[\s\S]*\}/);

if (!match) {
  throw new Error("Не вдалося знайти JSON у відповіді бота");
}

// Парсимо знайдений чистий JSON
const parsed = JSON.parse(match[0]);

// Функція для генерації надійного пароля
const generatePassword = () => {
  return Math.random().toString(36).slice(-10).toUpperCase() + Math.floor(Math.random() * 100) + "!";
};

// Генеруємо унікальні паролі
parsed.root_password = generatePassword();
parsed.cvat_superuser_password = generatePassword();
parsed.manager_password = generatePassword();

parsed.chat_space = $json.chat_space;

return parsed;
